// ─── COUNTDOWN HOOK ─────────────────────────────────────────────────────────
function useCountdown(minutes: number) {
  const [secondsLeft, setSecondsLeft] = useState(() => {
    const stored = sessionStorage.getItem("upsell_countdown_start");
    if (stored) {
      const elapsed = Math.floor((Date.now() - parseInt(stored)) / 1000);
      const remaining = minutes * 60 - elapsed;
      return remaining > 0 ? remaining : 0;
    }
    sessionStorage.setItem("upsell_countdown_start", Date.now().toString());
    return minutes * 60;
  });

  useEffect(() => {
    if (secondsLeft <= 0) return;
    const interval = setInterval(() => {
      setSecondsLeft((prev) => {
        if (prev <= 1) { clearInterval(interval); return 0; }
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  const mins = Math.floor(secondsLeft / 60);
  const secs = secondsLeft % 60;
  const progress = secondsLeft / (minutes * 60);
  return { mins, secs, secondsLeft, progress, expired: secondsLeft <= 0 };
}

